using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering.HighDefinition;using System;using System.Collections.Generic;using System.Linq;
public static class BuildLaunchRoom {
 const string Folder="Assets/LaunchRoom/";
 static Material metal,wall,floor,yellow;
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Stop Play mode first");AssetDatabase.Refresh();var h=GameObject.Find("Hangar 5 - Large").transform;if(GameObject.Find("Hangar 5 electrical launch room")!=null)throw new Exception("Room already exists");
 metal=Mat("Graphite steel",new Color(.075f,.095f,.11f),.6f);wall=Mat("Utility wall",new Color(.22f,.25f,.23f),.1f);floor=Mat("Utility concrete",new Color(.13f,.14f,.13f),0);yellow=Mat("Safety yellow",new Color(.8f,.5f,.035f),.1f);
 foreach(string name in new[]{"Wall Right","Timber Structure","Combined corrugated steel wall ribs"})Cut(h.Find("Combined structure/"+name));
 var root=new GameObject("Hangar 5 electrical launch room");root.transform.SetPositionAndRotation(h.TransformPoint(new Vector3(10.1f,.05f,5)),h.rotation*Quaternion.Euler(0,90,0));var r=root.transform;var seq=root.AddComponent<HangarLaunchSequence>();seq.hangar=h.GetComponentInChildren<HangarKeyDoor>(true);seq.grain=h.GetComponent<HangarGrainVisibility>().GrainRoot.GetComponent<GrainPile>();
 Cube(r,"Concrete base",new Vector3(0,-.12f,6),new Vector3(8.4f,.25f,12.5f),floor);
 Cube(r,"Left wall",new Vector3(-4.1f,3.5f,6),new Vector3(.25f,7,12.5f),wall);Cube(r,"Right wall",new Vector3(4.1f,3.5f,6),new Vector3(.25f,7,12.5f),wall);Cube(r,"Rear wall",new Vector3(0,3.5f,12.2f),new Vector3(8.4f,7,.25f),wall);Cube(r,"Roof",new Vector3(0,7,6),new Vector3(8.4f,.25f,12.5f),metal);
 Cube(r,"Entry left",new Vector3(-2.7f,3.5f,0),new Vector3(2.7f,7,.25f),wall);Cube(r,"Entry right",new Vector3(2.7f,3.5f,0),new Vector3(2.7f,7,.25f),wall);Cube(r,"Entry lintel",new Vector3(0,5.1f,0),new Vector3(2.7f,3.8f,.25f),wall);
 var pivot=Point(r,"Electrical door hinge",new Vector3(-1.25f,0,0));seq.roomDoor=pivot;var door=Cube(pivot,"Electrical room door",new Vector3(1.25f,1.55f,0),new Vector3(2.5f,3.1f,.14f),metal);var interaction=door.gameObject.AddComponent<LaunchRoomInteractable>();interaction.sequence=seq;Cube(door,"Handle",new Vector3(.35f,0,-1),new Vector3(.04f,.12f,1),yellow);
 Label(r,"ELECTRICAL\nAUTHORIZED PERSONNEL",new Vector3(0,2.2f,-.11f),Quaternion.Euler(0,180,0),.12f);seq.clearancePoint=Point(r,"Door clearance",new Vector3(0,0,-.7f));
 Model(r,"Electrical cabinet","Assets/Models/Electrical Box/Model/ElectricalBoxPKG.fbx",new Vector3(3.55f,0,3.4f),1.9f,Quaternion.Euler(0,-90,0));Model(r,"Transformer","Assets/Models/electrical-transformer/source/Electrical Transformer.fbx",new Vector3(-2.8f,0,3.8f),2.2f,Quaternion.identity);
 var box=Cube(r,"Main power switch housing",new Vector3(3.75f,1.45f,1.8f),new Vector3(.22f,.8f,.62f),metal);var sw=box.gameObject.AddComponent<LaunchRoomInteractable>();sw.sequence=seq;sw.isSwitch=true;seq.switchHandle=Point(r,"Power lever pivot",new Vector3(3.52f,1.4f,1.8f));seq.switchHandle.localRotation=Quaternion.Euler(0,0,-25);Cube(seq.switchHandle,"Power lever arm",new Vector3(-.15f,.20f,0),new Vector3(.07f,.5f,.07f),metal);Cube(seq.switchHandle,"Insulated grip",new Vector3(-.15f,.45f,0),new Vector3(.12f,.12f,.4f),yellow);
 Model(r,"Lever switch device","Assets/Models/lever-power-switch/source/Lever Switch.fbx",new Vector3(-3.6f,1.1f,1.5f),.75f,Quaternion.Euler(0,90,0));
 Label(r,"MAIN POWER",new Vector3(3.5f,2.08f,1.8f),Quaternion.Euler(0,-90,0),.10f);
 for(int i=0;i<3;i++)Cube(r,"Conduit "+i,new Vector3(3.85f,3.0f+i*.13f,2.6f),new Vector3(.05f,.05f,3),metal);
 var housing=Cube(r,"Hangar style lamp housing",new Vector3(0,4.3f,2.5f),new Vector3(1.2f,.14f,.5f),metal);var glow=Cube(r,"Lamp diffuser",new Vector3(0,4.20f,2.5f),new Vector3(1,.04f,.35f),Mat("Warm lamp",new Color(1,.82f,.5f),0));seq.lampGlow=glow.GetComponent<Renderer>();seq.lampGlow.enabled=false;
 var lamp=new GameObject("Electrical room ceiling light");lamp.transform.SetParent(r,false);lamp.transform.localPosition=new Vector3(0,4.0f,2.5f);seq.roomLight=lamp.AddComponent<Light>();lamp.AddComponent<HDAdditionalLightData>();seq.roomLight.type=LightType.Point;seq.roomLight.color=new Color(1,.8f,.5f);seq.roomLight.range=13;seq.roomLight.shadows=LightShadows.Soft;seq.roomLight.intensity=180;seq.roomLight.enabled=false;
 Cube(r,"Reveal left frame",new Vector3(-3,3.5f,5.4f),new Vector3(2.1f,7,.3f),wall);Cube(r,"Reveal right frame",new Vector3(3,3.5f,5.4f),new Vector3(2.1f,7,.3f),wall);Cube(r,"Reveal lintel",new Vector3(0,5.9f,5.4f),new Vector3(4,2.2f,.3f),wall);seq.revealDoor=Cube(r,"Concealed launch bay shutter",new Vector3(0,2.4f,5.4f),new Vector3(4,4.8f,.18f),metal);Label(seq.revealDoor,"DANGER\nHIGH VOLTAGE",new Vector3(0,0,-.6f),Quaternion.Euler(0,180,0),.04f);
 var rocket=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/Rocket Modular/Rocket Modular.prefab"));rocket.name="Hidden launch rocket";rocket.transform.SetParent(r,false);rocket.transform.localPosition=new Vector3(0,0,9);rocket.transform.localRotation=Quaternion.Euler(0,180,0);seq.rocketDoor=rocket.transform.Find("Entrance Door");var exhaust=rocket.transform.Find("Engine exhaust VFX");if(exhaust!=null)exhaust.gameObject.SetActive(false);
 seq.switchView=View(r,"Switch camera",new Vector3(2.3f,1.65f,1.8f),new Vector3(3.7f,1.5f,1.8f));seq.revealView=View(r,"Reveal camera",new Vector3(0,1.65f,2.4f),new Vector3(0,2,6.8f));seq.approachView=View(r,"Rocket approach",new Vector3(0,2.5f,6.8f),new Vector3(0,2.8f,9));seq.cabinView=View(r,"Cabin view",new Vector3(0,2.8f,9),new Vector3(0,2.7f,10.4f));
 seq.readyVoice=Clip("Ready");seq.threeVoice=Clip("Three");seq.twoVoice=Clip("Two");seq.oneVoice=Clip("One");seq.protestVoice=Clip("Protest");
 var scenes=EditorBuildSettings.scenes.ToList();foreach(var path in new[]{"Assets/Scenes/Gameplay.unity","Assets/Scenes/Last Scene.unity"}){int i=scenes.FindIndex(x=>x.path==path);if(i<0)scenes.Add(new EditorBuildSettingsScene(path,true));else scenes[i].enabled=true;}EditorBuildSettings.scenes=scenes.ToArray();
 EditorUtility.SetDirty(seq);EditorSceneManager.MarkSceneDirty(root.scene);EditorSceneManager.SaveOpenScenes();AssetDatabase.SaveAssets();Selection.activeGameObject=root;return "Built electrical room, doorway, switch, hidden rocket and launch sequence";
 }
 static AudioClip Clip(string n)=>AssetDatabase.LoadAssetAtPath<AudioClip>(Folder+"Audio/"+n+".wav");
 static Material Mat(string name,Color c,float metallic){var path=Folder+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("HDRP/Lit"));AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",c);m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",.3f);return m;}
 static Transform Point(Transform p,string n,Vector3 v){var t=new GameObject(n).transform;t.SetParent(p,false);t.localPosition=v;return t;}
 static Transform View(Transform p,string n,Vector3 v,Vector3 aim){var t=Point(p,n,v);t.rotation=Quaternion.LookRotation(p.TransformPoint(aim)-t.position,p.up);return t;}
 static Transform Cube(Transform p,string n,Vector3 v,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=v;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;return g.transform;}
 static void Label(Transform p,string text,Vector3 v,Quaternion rot,float size){var t=Point(p,text,v);t.localRotation=rot;var m=t.gameObject.AddComponent<TextMesh>();m.text=text;m.anchor=TextAnchor.MiddleCenter;m.alignment=TextAlignment.Center;m.characterSize=size;m.fontSize=48;m.color=new Color(.95f,.8f,.4f);}
 static void Model(Transform p,string name,string path,Vector3 pos,float height,Quaternion rotation){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(asset==null)throw new Exception(path);var g=(GameObject)PrefabUtility.InstantiatePrefab(asset);g.name=name;g.transform.SetParent(p,false);g.transform.localRotation=rotation;var renderers=g.GetComponentsInChildren<Renderer>();var b=new Bounds(g.transform.position,Vector3.zero);foreach(var rr in renderers)b.Encapsulate(rr.bounds);g.transform.localScale*=height/Mathf.Max(.001f,b.size.y);b=new Bounds(renderers[0].bounds.center,Vector3.zero);foreach(var rr in renderers)b.Encapsulate(rr.bounds);g.transform.position+=p.TransformPoint(pos)-new Vector3(b.center.x,b.min.y,b.center.z);foreach(var rr in renderers){var mats=rr.sharedMaterials;for(int i=0;i<mats.Length;i++)if(mats[i]==null||!mats[i].shader.name.StartsWith("HDRP"))mats[i]=metal;rr.sharedMaterials=mats;}var c=g.AddComponent<BoxCollider>();b=new Bounds(g.transform.InverseTransformPoint(renderers[0].bounds.center),Vector3.zero);foreach(var rr in renderers){b.Encapsulate(g.transform.InverseTransformPoint(rr.bounds.min));b.Encapsulate(g.transform.InverseTransformPoint(rr.bounds.max));}c.center=b.center;c.size=b.size;}
 struct V{public Vector3 p,n;public Vector2 uv;public static V Mix(V a,V b,float t)=>new V{p=Vector3.Lerp(a.p,b.p,t),n=Vector3.Lerp(a.n,b.n,t).normalized,uv=Vector2.Lerp(a.uv,b.uv,t)};}
 static void Cut(Transform t){var f=t.GetComponent<MeshFilter>();var source=f.sharedMesh;var vs=source.vertices;var ns=source.normals;var uv=source.uv;var verts=new List<Vector3>();var normals=new List<Vector3>();var uvs=new List<Vector2>();var subs=new List<int[]>();var planes=new[]{new Plane(Vector3.right,new Vector3(9.5f,0,0)),new Plane(Vector3.left,new Vector3(10.5f,0,0)),new Plane(Vector3.up,new Vector3(0,-.4f,0)),new Plane(Vector3.down,new Vector3(0,2.7f,0)),new Plane(Vector3.forward,new Vector3(0,0,4.3f)),new Plane(Vector3.back,new Vector3(0,0,5.7f))};
 for(int sm=0;sm<source.subMeshCount;sm++){var ids=new List<int>();var tris=source.GetTriangles(sm);for(int j=0;j<tris.Length;j+=3){var poly=new List<V>();for(int k=0;k<3;k++){int id=tris[j+k];poly.Add(new V{p=vs[id],n=ns[id],uv=uv.Length>id?uv[id]:Vector2.zero});}foreach(var plane in planes){var outside=new List<V>();var inside=new List<V>();for(int k=0;k<poly.Count;k++){var a=poly[k];var b=poly[(k+1)%poly.Count];float da=plane.GetDistanceToPoint(a.p),db=plane.GetDistanceToPoint(b.p);if(da>=0)inside.Add(a);else outside.Add(a);if((da>=0)!=(db>=0)){var v=V.Mix(a,b,da/(da-db));inside.Add(v);outside.Add(v);}}Emit(outside,verts,normals,uvs,ids);poly=inside;if(poly.Count<3)break;}}subs.Add(ids.ToArray());}
 var mesh=new Mesh{name="Hangar 5 doorway "+t.name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(verts);mesh.SetNormals(normals);mesh.SetUVs(0,uvs);mesh.subMeshCount=subs.Count;for(int i=0;i<subs.Count;i++)mesh.SetTriangles(subs[i],i);mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,Folder+"Doorway "+t.name+".asset");f.sharedMesh=mesh;var col=t.GetComponent<MeshCollider>();if(col!=null)col.sharedMesh=mesh;EditorUtility.SetDirty(f);if(col!=null)EditorUtility.SetDirty(col);}
 static void Emit(List<V> p,List<Vector3> v,List<Vector3> n,List<Vector2> uv,List<int> ids){if(p.Count<3)return;int start=v.Count;foreach(var a in p){v.Add(a.p);n.Add(a.n);uv.Add(a.uv);}for(int i=1;i<p.Count-1;i++){ids.Add(start);ids.Add(start+i);ids.Add(start+i+1);}}
}
